const e = $input.first().json;
const wf = e.workflow || {};
const exec = e.execution || {};
const nodeErr = e.trigger && e.trigger.error ? e.trigger.error : (exec.error || {});
const message = (nodeErr && nodeErr.message) || e.message || 'Sin mensaje de error';
const nodeName = (nodeErr && nodeErr.node && nodeErr.node.name) || 'desconocido';
const subject = `\uD83D\uDD34 BYG: fall\u00f3 el workflow "${wf.name || 'desconocido'}"`;
const body = `<b>Workflow:</b> ${wf.name || 'desconocido'} (${wf.id || '?'})<br>` +
  `<b>Nodo:</b> ${nodeName}<br>` +
  `<b>Execution ID:</b> ${exec.id || '?'}<br>` +
  `<b>Mensaje:</b> ${message}<br>` +
  `<b>URL:</b> ${exec.url || ''}`;
return [{ json: { subject, body } }];
